package gen:node;

world node {
    use aap:caps/types@0.1.0.{digest, published-digest};

    import aap:caps/notifier@0.1.0;

    export run: func(composed: digest) -> published-digest;
}
```

```rust
wit_bindgen::generate!({
    path: "wit",
    world: "node",
    generate_all,
});

use crate::aap::caps::notifier;

struct Node;

impl Guest for Node {
    fn run(composed: Digest) -> PublishedDigest {
        let message = render(&composed);
        let published = notifier::notify(&message);

        PublishedDigest {
            date: composed.date,
            considered: composed.considered,
            published,
        }
    }
}

fn render(d: &Digest) -> String {
    let mut out = String::new();
    out.push_str("Digest ");
    out.push_str(&d.date);
    out.push('\n');

    if !d.overview.is_empty() {
        out.push('\n');
        out.push_str(&d.overview);
        out.push('\n');
    }

    for entry in d.entries.iter().filter(|e| e.kept) {
        out.push('\n');
        out.push_str(&entry.title);
        out.push('\n');
        out.push_str(&entry.link);
        out.push('\n');
        if !entry.summary.is_empty() {
            out.push_str(&entry.summary);
            out.push('\n');
        }
    }

    out
}

export!(Node);
